func:
const kind = String(msg.payload);
const now = Math.floor(Date.now() / 1000);
let seq = flow.get("part4DemoSeq") || 0;
seq += 1;
flow.set("part4DemoSeq", seq);

const sample = {
    v: 1,
    device: "DEMO-ONLY-DEVICE",
    seq,
    ts: now,
    temp: 26.4,
    humi: 63.0,
    light: 2048,
    status: "ok"
};

if (kind === "invalid") {
    sample.temp = "26.4";
    sample.humi = 130;
}
if (kind === "stale") {
    sample.ts = now - 300;
}

msg.payload = sample;
msg.demo = true;
msg.demoCase = kind;
return msg;

const required = ["v", "device", "seq", "ts", "temp", "humi", "light", "status"];
const p = msg.payload;
const errors = [];

if (!p || typeof p !== "object" || Array.isArray(p)) {
    errors.push("payload is not an object");
} else {
    const keys = Object.keys(p);
    if (keys.length !== required.length || required.some((key) => !Object.prototype.hasOwnProperty.call(p, key))) {
        errors.push("fields must match the Part 3 schema exactly");
    }
    if (p.v !== 1) errors.push("v must be 1");
    if (typeof p.device !== "string" || !/^[A-Za-z0-9-]{1,23}$/.test(p.device)) errors.push("invalid device alias");
    if (!Number.isSafeInteger(p.seq) || p.seq < 1 || p.seq > 4294967295) errors.push("seq must be integer 1..4294967295");
    if (!Number.isSafeInteger(p.ts) || p.ts <= 1700000000) errors.push("invalid Unix timestamp");
    if (typeof p.temp !== "number" || !Number.isFinite(p.temp) || p.temp < -20 || p.temp > 80) errors.push("temp out of range/type");
    if (typeof p.humi !== "number" || !Number.isFinite(p.humi) || p.humi < 0 || p.humi > 100) errors.push("humi out of range/type");
    if (!Number.isInteger(p.light) || p.light < 0 || p.light > 4095) errors.push("light out of range/type");
    if (p.status !== "ok") errors.push("status must be ok");
    if (Buffer.byteLength(JSON.stringify(p), "utf8") > 384) errors.push("payload exceeds 384 bytes");
}

if (errors.length) {
    const quality = { payload: `DEMO ONLY | INVALID | ${errors.join("; ")} | widgets not updated` };
    node.status({ fill: "red", shape: "ring", text: "INVALID" });
    return [null, quality];
}

const now = Math.floor(Date.now() / 1000);
const age = now - p.ts;
if (age < -5) {
    node.status({ fill: "red", shape: "ring", text: "FUTURE TS" });
    return [null, { payload: `DEMO ONLY | INVALID | timestamp is ${-age}s in the future | widgets not updated` }];
}
if (age > 10) {
    node.status({ fill: "yellow", shape: "ring", text: `STALE ${age}s` });
    return [null, { payload: `DEMO ONLY | STALE | age ${age}s exceeds 10s | widgets show last accepted history` }];
}

msg.dashboardMode = "DEMO";
msg.telemetryAge = age;
node.status({ fill: "green", shape: "dot", text: `VALID age ${age}s` });
return [msg, { payload: `DEMO ONLY | VALID | age ${age}s | not hardware data` }];

const p = msg.payload;
const mode = msg.dashboardMode === "LIVE" ? "LIVE" : "DEMO ONLY";
const at = p.ts * 1000;
const temp = { payload: p.temp };
const humi = { payload: p.humi };
const light = { payload: p.light };
const chartTemp = { topic: "temperature", payload: p.temp, timestamp: at };
const chartHumi = { topic: "humidity", payload: p.humi, timestamp: at };
const summary = { payload: `${mode} | ${p.device} | seq ${p.seq} | age ${msg.telemetryAge}s` };
return [temp, humi, light, [chartTemp, chartHumi], summary];

function reject(code) {
    const source = msg.demo === true ? "DEMO" : "INPUT";
    node.status({ fill: "red", shape: "ring", text: code });
    return [null, { payload: `${source} | ${code} | widgets not updated` }, null];
}

const validation = msg.validation;
if (!validation || validation.ok !== true || validation.code !== "OK" || !Number.isInteger(validation.age_s)) {
    const code = typeof validation?.code === "string" && /^[A-Z0-9_]{1,24}$/.test(validation.code)
        ? validation.code
        : "VALIDATION_REQUIRED";
    return reject(code);
}

const p = msg.payload;
const expected = ["device", "humi", "light", "seq", "status", "temp", "ts", "v"];
if (!p || typeof p !== "object" || Array.isArray(p) ||
    Object.keys(p).sort().join(",") !== expected.join(",")) {
    return reject("EIGHT_FIELD_PAYLOAD_REQUIRED");
}
if (validation.age_s < -5 || validation.age_s > 10) {
    return reject(validation.age_s > 10 ? "STALE" : "TIME_FUTURE");
}

const isDemo = msg.demo === true;
msg.dashboardMode = isDemo ? "DEMO" : "LIVE";
msg.telemetryAge = validation.age_s;
const label = isDemo ? "DEMO ONLY" : "LIVE";
const quality = { payload: `${label} | VALID | age ${validation.age_s}s${isDemo ? " | not hardware data" : ""}` };
const livePulse = isDemo ? null : { payload: `LIVE | fresh validated telemetry | age ${validation.age_s}s` };
node.status({ fill: isDemo ? "blue" : "green", shape: "dot", text: `${label} age ${validation.age_s}s` });
return [msg, quality, livePulse];
